        "daemonDesc": "Pitää ilmoitukset tulossa sovelluksen sulkemisen jälkeen. systemd:tä ei voi ohjata hiekkalaatikosta - napauta komentoa alla kopioidaksesi, liitä sitten Terminaaliin. Käynnistä sovellus uudelleen aktivoinnin jälkeen, jos tila ei vaihdu käynnissä-tilaan muutamassa sekunnissa. Ilmoitusten poiskytkentä pysäyttää vain käynnissä olevan daemonin - automaattikäynnistyksen poisto vaatii disable-komennon alla.",
        "sailjailHeader": "Sailjail-oikeudet",
        "sailjailDesc": "Sailfish OS:ssä ei ole ajonaikaisia oikeusdialogeja, eikä sovellus voi muokata omaa desktop-tiedostoaan hiekkalaatikosta. Sovellus toimitetaan siksi MINIMAALISIN oikeuksin (Internet, Secrets). Napauta komentoa alla kopioidaksesi, aja Terminaalissa, käynnistä sovellus uudelleen. Päivitykset eivät ylikirjoita valintaasi.\n\nIlman mediatallennusoikeutta vastaanotettu media tallentuu sovelluksen yksityiseen datakansioon (ei näy Galleriassa) ja kuva-/tiedostovalitsimet näyttävät tyhjiltä.",
