        "daemonDesc": "Håller aviseringarna igång efter att appen stängts. systemd kan inte styras inifrån sandlådan - tryck på ett kommando nedan för att kopiera, klistra in i Terminal. Starta om appen efter aktivering om statusen inte växlar till körs inom några sekunder. Att stänga av aviseringar stoppar bara den körande demonen - att helt ta bort autostarten kräver disable-kommandot nedan.",
        "sailjailHeader": "Sailjail-behörigheter",
        "sailjailDesc": "Sailfish OS saknar behörighetsdialoger vid körning, och appen kan inte redigera sin egen desktop-fil inifrån sandlådan. Appen levereras därför med MINIMALA behörigheter (Internet, Secrets). Tryck på ett kommando nedan för att kopiera, kör i Terminal, starta om appen. Uppdateringar skriver inte över ditt val.\n\nUtan medielagringsbehörighet sparas mottagna medier i appens privata datamapp (syns inte i Galleriet) och bild-/filväljarna ser tomma ut.",
