        "copyGrantAudioSensors": "Kopiera kommando: GE audio+sensorbehörigheter (lyssna på röstmeddelanden vid örat, inkl. volymkontroll). Obs: systemdialogen säger 'Spela upp och spela in ljud' - det är OS-namnet på själva Audio-behörigheten (ljudströmmar går ännu inte att skilja åt). Appen spelar aldrig in med enbart dessa behörigheter: inspelning sker bara via mikrofonknappen, som dessutom kräver Mikrofon-behörigheten och annars vägrar",
