        "daemonDesc": "Az értesítéseket az app bezárása után is életben tartja. A systemd nem vezérelhető a homokozóból - koppints egy alábbi parancsra a másoláshoz, majd illeszd be a Terminálba. Aktiválás után indítsd újra az appot, ha az állapot pár másodpercen belül nem vált futóra. Az értesítések kikapcsolása csak a futó démont állítja le - az automatikus indítás teljes eltávolításához az alábbi disable parancs kell.",
        "sailjailHeader": "Sailjail-engedélyek",
        "sailjailDesc": "A Sailfish OS-ben nincsenek futásidejű engedélykérő ablakok, és az app a homokozóból nem szerkesztheti a saját desktop-fájlját. Ezért az app MINIMÁLIS engedélyekkel érkezik (Internet, Secrets). Koppints egy alábbi parancsra a másoláshoz, futtasd Terminálban, majd indítsd újra az appot. A frissítések nem írják felül a választásodat.\n\nMédiatárhely-engedély nélkül a fogadott média az app privát adatmappájába kerül (a Galériában nem látszik), és a kép-/fájlválasztók üresnek tűnnek.",
