        "chatGridDesc": "Показывать чаты плитками с аватаром в качестве фона вместо списка. Меню долгого нажатия (закрепить, без звука, архив) остаётся в списочном виде",
        "tilesPerRow": "Плиток в ряду",
        "tileSpacing": "\u041e\u0442\u0441\u0442\u0443\u043f \u043c\u0435\u0436\u0434\u0443 \u043f\u043b\u0438\u0442\u043a\u0430\u043c\u0438",
        "aboutApp": "\u041e \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438",
        "aboutSubtitle": "\u041d\u0435\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043a\u043b\u0438\u0435\u043d\u0442 WhatsApp \u0434\u043b\u044f Sailfish OS",
        "aboutDeveloper": "\u0420\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0447\u0438\u043a: Sebastian Matkovich (smatkovi), \u0412\u0435\u043d\u0430",
