        "daemonDesc": "Сохраняет уведомления после закрытия приложения. systemd нельзя управлять из песочницы - нажмите на команду ниже, чтобы скопировать, вставьте в Терминал. После включения перезапустите приложение, если статус не сменится на работает за несколько секунд. Отключение уведомлений останавливает только работающий демон - для полного удаления автозапуска нужна команда disable ниже.",
        "sailjailHeader": "Разрешения Sailjail",
        "sailjailDesc": "В Sailfish OS нет диалогов разрешений во время работы, а приложение не может редактировать свой desktop-файл из песочницы. Поэтому приложение поставляется с МИНИМАЛЬНЫМИ разрешениями (Интернет, Secrets). Нажмите на команду ниже, чтобы скопировать, выполните в Терминале, перезапустите приложение. Обновления не перезапишут ваш выбор.\n\nБез разрешения на медиахранилище полученные медиа сохраняются в приватной папке приложения (не видны в Галерее), а выбор изображений/файлов выглядит пустым.",
