        "contacts": "Contacts",
        "daemonDesc": "Maintient les notifications après la fermeture de l'appli. systemd ne peut pas être piloté depuis le bac à sable - touchez une commande ci-dessous pour la copier, collez-la dans le Terminal. Après activation, relancez l'appli si le statut ne passe pas à actif en quelques secondes. Désactiver les notifications n'arrête que le démon en cours - retirer complètement le démarrage automatique demande la commande disable ci-dessous.",
        "sailjailHeader": "Permissions Sailjail",
        "sailjailDesc": "Sailfish OS n'a pas de dialogues de permission à l'exécution, et l'appli ne peut pas modifier son propre fichier desktop depuis le bac à sable. Elle est donc livrée avec des permissions MINIMALES (Internet, Secrets). Touchez une commande ci-dessous pour la copier, exécutez-la dans le Terminal, relancez l'appli. Les mises à jour n'écrasent pas votre choix.\n\nSans permission de stockage média, les médias reçus vont dans le dossier privé de l'appli (invisibles dans la Galerie) et les sélecteurs d'images/fichiers semblent vides.",
        "copyGrantContacts": "Copier la commande : ACCORDER la permission contacts",
