        "copyGrantAudioSensors": "Copier la commande : ACCORDER les permissions audio+capteurs (écouter les vocaux à l'oreille, avec réglage du volume écouteur). Note : le système affichera 'Lire et enregistrer l'audio' - c'est le nom OS de la permission Audio elle-même (les flux ne sont pas encore séparables). L'appli n'enregistre jamais avec ces seules permissions : l'enregistrement passe uniquement par le bouton micro, qui exige en plus la permission Micro et refuse sinon",
        "copyRevokeAudioSensors": "Copier la commande : RÉVOQUER les permissions audio+capteurs",
