        "topSwitcher": "Επιλογέας προβολής επάνω",
        "topSwitcherDesc": "Τα κουμπιά λίστα/2/3/4/5/6 πάνω από τις συνομιλίες",
        "bottomBar": "Κάτω γραμμή πλοήγησης",
        "bottomBarDesc": "Αρχείο, Αγαπημένα, Συνομιλίες και Κατάσταση κάτω - οι χειρονομίες σάρωσης λειτουργούν πάντα",
        "chatGrid": "Προβολή πλέγματος",
        "tilesPerRow": "Πλακίδια ανά σειρά",
        "tileSpacing": "\u0391\u03c0\u03cc\u03c3\u03c4\u03b1\u03c3\u03b7 \u03c0\u03bb\u03b1\u03ba\u03b9\u03b4\u03af\u03c9\u03bd",
        "aboutApp": "\u03a3\u03c7\u03b5\u03c4\u03b9\u03ba\u03ac",
        "aboutSubtitle": "\u0391\u03bd\u03b5\u03c0\u03af\u03c3\u03b7\u03bc\u03bf\u03c2 \u03b5\u03b3\u03b3\u03b5\u03bd\u03ae\u03c2 \u03c0\u03b5\u03bb\u03ac\u03c4\u03b7\u03c2 WhatsApp \u03b3\u03b9\u03b1 \u03c4\u03bf Sailfish OS",
        "aboutDeveloper": "\u0391\u03bd\u03ac\u03c0\u03c4\u03c5\u03be\u03b7: Sebastian Matkovich (smatkovi), \u0392\u03b9\u03ad\u03bd\u03bd\u03b7",
        "aboutSource": "\u03a0\u03b7\u03b3\u03b1\u03af\u03bf\u03c2 \u03ba\u03ce\u03b4\u03b9\u03ba\u03b1\u03c2 \u03c3\u03c4\u03bf GitHub",
        "aboutIssues": "\u0391\u03bd\u03b1\u03c6\u03bf\u03c1\u03ac \u03c0\u03c1\u03bf\u03b2\u03bb\u03ae\u03bc\u03b1\u03c4\u03bf\u03c2",
        "aboutDonate": "\u03a5\u03c0\u03bf\u03c3\u03c4\u03b7\u03c1\u03af\u03be\u03c4\u03b5 \u03c4\u03b7\u03bd \u03b1\u03bd\u03ac\u03c0\u03c4\u03c5\u03be\u03b7",
        "aboutDonatePaypal": "\u0394\u03c9\u03c1\u03b5\u03ac \u03bc\u03ad\u03c3\u03c9 PayPal",
        "aboutDonateLiberapay": "\u0394\u03c9\u03c1\u03b5\u03ac \u03bc\u03ad\u03c3\u03c9 Liberapay",
        "aboutThanks": "\u0395\u03c5\u03c7\u03b1\u03c1\u03b9\u03c3\u03c4\u03af\u03b5\u03c2 \u03c3\u03c4\u03b7\u03bd \u03ba\u03bf\u03b9\u03bd\u03cc\u03c4\u03b7\u03c4\u03b1: rdomschk (\u03b3\u03b5\u03c1\u03bc\u03b1\u03bd\u03b9\u03ba\u03ae \u03bc\u03b5\u03c4\u03ac\u03c6\u03c1\u03b1\u03c3\u03b7 \u03ba\u03b1\u03b9 \u03b1\u03ba\u03bf\u03cd\u03c1\u03b1\u03c3\u03c4\u03b5\u03c2 \u03b4\u03bf\u03ba\u03b9\u03bc\u03ad\u03c2), kempertom, tom_i, rob_k \u03ba\u03b1\u03b9 \u03c3\u03b5 \u03cc\u03bb\u03bf\u03c5\u03c2 \u03cc\u03c3\u03bf\u03b9 \u03b1\u03bd\u03b1\u03c6\u03ad\u03c1\u03bf\u03c5\u03bd \u03c0\u03c1\u03bf\u03b2\u03bb\u03ae\u03bc\u03b1\u03c4\u03b1 \u03ba\u03b1\u03b9 \u03b9\u03b4\u03ad\u03b5\u03c2 \u03c3\u03c4\u03bf OpenRepos. \u039f\u03b9 \u03bc\u03b5\u03c4\u03b1\u03c6\u03c1\u03ac\u03c3\u03b5\u03b9\u03c2 \u03c3\u03c4\u03b7\u03c1\u03af\u03b6\u03bf\u03bd\u03c4\u03b1\u03b9 \u03c3\u03c4\u03b7\u03bd \u03ba\u03bf\u03b9\u03bd\u03cc\u03c4\u03b7\u03c4\u03b1 - \u03bf\u03b9 \u03b4\u03b9\u03bf\u03c1\u03b8\u03ce\u03c3\u03b5\u03b9\u03c2 \u03b5\u03af\u03bd\u03b1\u03b9 \u03b1\u03bb\u03bb\u03b1\u03b3\u03ad\u03c2 \u03bc\u03af\u03b1\u03c2 \u03b3\u03c1\u03b1\u03bc\u03bc\u03ae\u03c2 \u03c3\u03c4\u03bf qml/translations.js.",
        "aboutPowered": "\u0392\u03b1\u03c3\u03af\u03b6\u03b5\u03c4\u03b1\u03b9 \u03c3\u03c4\u03b7 \u03b2\u03b9\u03b2\u03bb\u03b9\u03bf\u03b8\u03ae\u03ba\u03b7 whatsmeow \u03c4\u03bf\u03c5 Tulir Asokan. \u03a0\u03c1\u03cc\u03ba\u03b5\u03b9\u03c4\u03b1\u03b9 \u03b3\u03b9\u03b1 \u03b1\u03bd\u03b5\u03c0\u03af\u03c3\u03b7\u03bc\u03bf \u03c0\u03b5\u03bb\u03ac\u03c4\u03b7 \u03c0\u03bf\u03c5 \u03b4\u03b5\u03bd \u03c3\u03c7\u03b5\u03c4\u03af\u03b6\u03b5\u03c4\u03b1\u03b9 \u03bc\u03b5 \u03c4\u03bf WhatsApp \u03ae \u03c4\u03b7 Meta.",
